ALTER TABLE public.outbox_events ADD COLUMN schema_version integer NOT NULL DEFAULT 1,ADD COLUMN publish_status varchar(16) NOT NULL DEFAULT 'pending',ADD COLUMN published_at timestamptz,ADD COLUMN topic varchar(160),ADD COLUMN partition_key text,ADD CONSTRAINT outbox_schema_version_positive CHECK(schema_version>0),ADD CONSTRAINT outbox_publish_status_check CHECK(publish_status IN('pending','publishing','published','failed'));
CREATE TABLE public.consumer_receipts(consumer_group varchar(160) NOT NULL,event_id uuid NOT NULL,processed_at timestamptz NOT NULL DEFAULT now(),result_code varchar(80) NOT NULL,PRIMARY KEY(consumer_group,event_id));
CREATE TABLE public.event_dead_letters(id bigserial PRIMARY KEY,event_id uuid NOT NULL,consumer_group varchar(160) NOT NULL,topic varchar(160) NOT NULL,error_code varchar(80) NOT NULL,attempt_count integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,consumer_group));
GRANT SELECT,INSERT,UPDATE ON public.consumer_receipts,public.event_dead_letters TO cortex_app;GRANT USAGE,SELECT ON SEQUENCE public.event_dead_letters_id_seq TO cortex_app;
